import { literal } from "pg-format";
// src/vendor/postgres-meta/lib/helpers.ts
const coalesceRowsToArray = (source, filter) => {
	return `
COALESCE(
  (
    SELECT
      array_agg(row_to_json(${source})) FILTER (WHERE ${filter})
    FROM
      ${source}
  ),
  '{}'
) AS ${source}`;
};
const filterByList = (include, exclude, defaultExclude) => {
	if (defaultExclude) exclude = defaultExclude.concat(exclude ?? []);
	if (include?.length) return `IN (${include.map(literal).join(",")})`;
	else if (exclude?.length) return `NOT IN (${exclude.map(literal).join(",")})`;
	return "";
};
const filterByValue = (ids) => {
	if (ids?.length) return `IN (${ids.map(literal).join(",")})`;
	return "";
};
export { coalesceRowsToArray, filterByList, filterByValue };
